/**
 * @fileoverview Lume Tooltip Engine - Lightweight, zero-dependency contextual tooltip engine.
 * @module @staticcanvas/lume
 * @license MIT
 */

let tooltipIdCounter = 0;

/**
 * @typedef {Object} LumeOptions
 * @property {string} [selector='[data-lume], [data-lume-content]'] CSS selector for automatically initialized triggers.
 * @property {number} [offset=14] Distance in pixels between a trigger and its tooltip.
 * @property {boolean} [smart=true] Flip placement when the preferred side lacks space; `auto` chooses the side with the most room.
 * @property {Array<'top'|'bottom'|'left'|'right'>} [priority] Ordered sides used by `auto` placement.
 * @property {string} [className=''] Additional class names applied to the tooltip.
 * @property {'minimal'|'simple'|'advanced'} [tier='simple'] Tooltip density tier.
 * @property {'fade'|'lift'|'scale'|'slide'|'pop'|'blur'|'bounce'|'swing'|'flip'|'none'} [motion='fade'] Tooltip motion preset.
 * @property {string} [icon=''] Application-owned SVG URL or `info` icon displayed before the title.
 * @property {string} [dot=''] Optional CSS color for a circular status dot.
 * @property {'left'|'right'|'top'|'bottom'} [dotPosition='left'] Position of the status dot.
 * @property {'left'|'center'|'right'} [align='center'] Horizontal alignment for top and bottom placement.
 * @property {'hover'|'click'} [action='hover'] Trigger interaction model.
 * @property {number} [motionIntensity=1] Motion strength from 0 through 3.
 * @property {number} [showDelay=0] Show delay in milliseconds.
 * @property {number} [hideDelay=0] Hide delay in milliseconds.
 * @property {boolean} [allowHTML=false] Render trusted `data-lume-content` as HTML.
 * @property {HTMLElement|null} [container] Element receiving the tooltip node.
 * @property {HTMLElement|null} [boundary] Element constraining tooltip placement.
 * @property {number} [padding=10] Minimum distance from the positioning boundary.
 * @property {boolean} [autoInit=true] Initialize matching triggers during construction.
 * @property {boolean} [observeMutations=true] Bind matching triggers added after initialization.
 */

/**
 * @typedef {Object} LumeElementConfig
 * @property {string} title Resolved tooltip title.
 * @property {string} content Resolved tooltip content.
 * @property {string} icon Resolved icon URL or the built-in `info` icon.
 * @property {string} dot Resolved status-dot color.
 * @property {'left'|'right'|'top'|'bottom'} dotPosition Resolved status-dot position.
 * @property {'left'|'center'|'right'} align Resolved horizontal alignment.
 * @property {'auto'|'top'|'bottom'|'left'|'right'} direction Resolved placement direction.
 * @property {Array<'top'|'bottom'|'left'|'right'>} priority Ordered placement priority.
 * @property {number} offset Resolved trigger-to-tooltip distance.
 * @property {string} customClass Resolved custom class names.
 * @property {'minimal'|'simple'|'advanced'} tier Resolved tooltip density tier.
 * @property {'fade'|'lift'|'scale'|'slide'|'pop'|'blur'|'bounce'|'swing'|'flip'|'none'} motion Resolved motion preset.
 * @property {number} motionIntensity Resolved motion strength.
 * @property {'hover'|'click'} action Resolved interaction model.
 * @property {boolean} smart Whether collision flipping is enabled.
 */

export class Lume {
  /**
   * Initializes a new Lume tooltip instance.
   * @param {LumeOptions} [options={}] - Configuration options for Lume.
   * @param {string} [options.selector='[data-lume], [data-lume-content]'] - Target attribute or selector for auto-initialization.
   * @param {number} [options.offset=14] - Distance in pixels between target element and tooltip.
   * @param {boolean} [options.smart=true] - Enables collision detection; `data-lume-direction="auto"` chooses the side with the most room.
   * @param {Array<'top'|'bottom'|'left'|'right'>} [options.priority] - Ordered sides preferred by automatic placement.
   * @param {string} [options.className=''] - Custom CSS class appended to tooltip element.
   * @param {'minimal'|'simple'|'advanced'} [options.tier='simple'] - Tooltip density tier.
   * @param {'fade'|'lift'|'scale'|'slide'|'pop'|'blur'|'bounce'|'swing'|'flip'|'none'} [options.motion='fade'] - Visual motion preset.
   * @param {string} [options.icon=''] - Optional application-owned SVG URL or `info` icon shown before the tooltip title.
   * @param {string} [options.dot=''] - Optional CSS color for a circular status dot.
   * @param {'left'|'right'|'top'|'bottom'} [options.dotPosition='left'] - Position of the status dot.
   * @param {'left'|'center'|'right'} [options.align='center'] - Horizontal alignment for top and bottom tooltip placement.
   * @param {'hover'|'click'} [options.action='hover'] - Trigger interaction model. Click mode supports mouse, touch, and keyboard activation.
   * @param {number} [options.motionIntensity=1] - Scales the strength of the selected motion preset from 0 to 3.
   * @param {number} [options.showDelay=0] - Delay in milliseconds before showing a tooltip.
   * @param {number} [options.hideDelay=0] - Delay in milliseconds before hiding a tooltip.
   * @param {boolean} [options.allowHTML=false] - Render trusted data-lume-content as HTML when explicitly enabled.
   * @param {HTMLElement} [options.container] - DOM element to append tooltip to (defaults to document.body).
   * @param {HTMLElement} [options.boundary] - Element whose visible bounds constrain the tooltip.
   * @param {number} [options.padding=10] - Minimum distance from the positioning boundary.
   * @param {boolean} [options.autoInit=true] - Automatically bind matching elements and observe DOM mutations.
   * @param {boolean} [options.observeMutations=true] - Automatically bind matching elements added after initialization.
   */
  constructor(options = {}) {
    this.options = {
      selector: '[data-lume], [data-lume-content]',
      offset: 14,
      smart: true,
      priority: ['top', 'bottom', 'right', 'left'],
      className: '',
      tier: 'simple',
      dot: '',
      dotPosition: 'left',
      motion: 'fade',
      icon: '',
      align: 'center',
      action: 'hover',
      motionIntensity: 1,
      showDelay: 0,
      hideDelay: 0,
      allowHTML: false,
      container: null,
      boundary: null,
      padding: 10,
      autoInit: true,
      observeMutations: true,
      ...options,
    };

    this._validateOptions();

    /** @type {HTMLElement|null} */
    this.tooltip = null;
    /** @type {HTMLElement|null} */
    this.activeEl = null;
    /** @type {MutationObserver|null} */
    this.observer = null;
    /** @type {WeakSet<HTMLElement>} */
    this.boundElements = new WeakSet();
    this.elementHandlers = new Map();
    this.interactionState = new WeakMap();
    this._showTimer = null;
    this._hideTimer = null;
    this._repositionFrame = null;
    this._resizeObserver = null;

    this._scrollRef = () => this.requestReposition();
    this._clickRef = (event) => {
      if (!this.activeEl || this._getElementConfig(this.activeEl).action !== 'click') return;
      if (event.target === this.activeEl || this.activeEl.contains(event.target)) return;
      this.hide();
    };
    this._keyRef = (event) => {
      if (event.key === 'Escape') this.hide();
    };

    if (this.options.autoInit && typeof document !== 'undefined') {
      this.init();
      if (this.options.observeMutations) this._initObserver();
    }
    if (typeof document !== 'undefined') {
      document.addEventListener('keydown', this._keyRef);
      document.addEventListener('click', this._clickRef);
    }
  }

  /**
   * Normalizes invalid public options and reports actionable diagnostics.
   * @returns {void}
   * @private
   */
  _validateOptions() {
    const numericDefaults = {
      offset: 14,
      padding: 10,
      showDelay: 0,
      hideDelay: 0,
      motionIntensity: 1,
    };
    for (const [key, fallback] of Object.entries(numericDefaults)) {
      const value = Number(this.options[key]);
      if (!Number.isFinite(value) || value < 0) {
        if (typeof console !== 'undefined' && typeof console.warn === 'function') {
          console.warn(`[Lume] Invalid ${key}; using ${fallback}.`);
        }
        this.options[key] = fallback;
      } else {
        this.options[key] = value;
      }
    }
    this.options.motionIntensity = Math.max(0, Math.min(3, this.options.motionIntensity));
    if (!['hover', 'click'].includes(this.options.action)) {
      if (typeof console !== 'undefined' && typeof console.warn === 'function') {
        console.warn(`[Lume] Invalid action; using hover.`);
      }
      this.options.action = 'hover';
    }
    if (!['minimal', 'simple', 'advanced'].includes(this.options.tier)) {
      if (typeof console !== 'undefined' && typeof console.warn === 'function') {
        console.warn('[Lume] Invalid tier; using simple.');
      }
      this.options.tier = 'simple';
    }
    if (!['left', 'right', 'top', 'bottom'].includes(this.options.dotPosition)) {
      if (typeof console !== 'undefined' && typeof console.warn === 'function') {
        console.warn('[Lume] Invalid dotPosition; using left.');
      }
      this.options.dotPosition = 'left';
    }
    if (!['left', 'center', 'right'].includes(this.options.align)) {
      if (typeof console !== 'undefined' && typeof console.warn === 'function') {
        console.warn(`[Lume] Invalid align; using center.`);
      }
      this.options.align = 'center';
    }
    const fallbackPriority = ['top', 'bottom', 'right', 'left'];
    const priority = Array.isArray(this.options.priority)
      ? this.options.priority
      : typeof this.options.priority === 'string'
        ? this.options.priority.split(',')
        : [];
    this.options.priority = [
      ...new Set(priority.filter((side) => fallbackPriority.includes(side))),
    ];
    if (!this.options.priority.length) this.options.priority = fallbackPriority;

    if (typeof this.options.selector !== 'string' || !this.options.selector.trim()) {
      this.options.selector = '[data-lume], [data-lume-content]';
      if (typeof console !== 'undefined' && typeof console.warn === 'function') {
        console.warn('[Lume] Invalid selector; using [data-lume], [data-lume-content].');
      }
      return;
    }

    if (typeof document !== 'undefined') {
      try {
        document.querySelector(this.options.selector);
      } catch {
        this.options.selector = '[data-lume], [data-lume-content]';
        if (typeof console !== 'undefined' && typeof console.warn === 'function') {
          console.warn('[Lume] Invalid selector; using [data-lume], [data-lume-content].');
        }
      }
    }
  }

  /**
   * Scans the document and attaches event listeners to matching elements.
   * @returns {void}
   */
  init() {
    if (typeof document === 'undefined') return;
    const elements = document.querySelectorAll(this.options.selector);
    elements.forEach((el) => {
      if (el instanceof HTMLElement) {
        this._bindEvents(el);
      }
    });
  }

  /**
   * Binds interaction events to a target element.
   * @param {HTMLElement} el - Element to bind.
   * @returns {void}
   * @private
   */
  _bindEvents(el) {
    if (!el || this.boundElements.has(el)) return;

    const state = { pointer: false, focus: false };
    const handlers = {
      mouseenter: () => {
        if (this._getElementConfig(el).action !== 'hover') return;
        state.pointer = true;
        this.show(el);
      },
      mouseleave: () => {
        if (this._getElementConfig(el).action !== 'hover') return;
        state.pointer = false;
        if (!state.focus) this.hide();
      },
      focus: () => {
        if (this._getElementConfig(el).action !== 'hover') return;
        state.focus = true;
        this.show(el);
      },
      blur: () => {
        if (this._getElementConfig(el).action !== 'hover') return;
        state.focus = false;
        if (!state.pointer) this.hide();
      },
      click: () => {
        if (this._getElementConfig(el).action !== 'click') return;
        if (this.activeEl === el) this.hide();
        else this.show(el);
      },
      keydown: (event) => {
        if (this._getElementConfig(el).action !== 'click' || !['Enter', ' '].includes(event.key))
          return;
        event.preventDefault();
        el.click();
      },
    };

    el.addEventListener('mouseenter', handlers.mouseenter);
    el.addEventListener('mouseleave', handlers.mouseleave);
    el.addEventListener('focus', handlers.focus);
    el.addEventListener('blur', handlers.blur);
    el.addEventListener('click', handlers.click);
    el.addEventListener('keydown', handlers.keydown);

    this.interactionState.set(el, state);
    this.elementHandlers.set(el, handlers);
    this.boundElements.add(el);
  }

  /**
   * Initializes MutationObserver to monitor DOM additions and removals.
   * @returns {void}
   * @private
   */
  _initObserver() {
    if (typeof MutationObserver === 'undefined' || typeof document === 'undefined') return;

    this.observer = new MutationObserver((mutations) => {
      for (const mutation of mutations) {
        // Handle dynamically added nodes
        mutation.addedNodes.forEach((node) => {
          if (node.nodeType !== 1) return;
          const element = /** @type {HTMLElement} */ (node);
          if (element.matches && element.matches(this.options.selector)) {
            this._bindEvents(element);
          }
          if (element.querySelectorAll) {
            element.querySelectorAll(this.options.selector).forEach((child) => {
              if (child instanceof HTMLElement) {
                this._bindEvents(child);
              }
            });
          }
        });

        // Handle dynamically removed nodes (prevent orphan / ghost tooltips)
        if (this.activeEl) {
          mutation.removedNodes.forEach((node) => {
            if (node === this.activeEl || (node.contains && node.contains(this.activeEl))) {
              this.hide();
            }
          });
        }
      }
    });

    const targetContainer = this.options.container || document.body;
    if (targetContainer) {
      this.observer.observe(targetContainer, { childList: true, subtree: true });
    }
  }

  /**
   * Creates or returns the single reusable tooltip DOM node.
   * @private
   * @returns {HTMLElement}
   */
  _create() {
    if (this.tooltip) return this.tooltip;

    const div = document.createElement('div');
    div.className = 'lume-tooltip';
    div.setAttribute('role', 'tooltip');
    div.setAttribute('aria-hidden', 'true');
    // Keep the newly-created node out of layout until its first position is ready.
    div.style.display = 'none';
    div.innerHTML =
      '<div class="lume-header"></div><div class="lume-content"></div><span class="lume-dot" aria-hidden="true"></span><div class="lume-arrow"></div>';

    const container = this.options.container || document.body;
    container.appendChild(div);
    this.tooltip = div;
    return div;
  }

  /**
   * Resolves configuration for a specific trigger element.
   * @param {HTMLElement} el - Trigger element.
   * @private
   * @returns {LumeElementConfig}
   */
  _getElementConfig(el) {
    const title = el.getAttribute('data-lume-title') || '';
    const icon = el.getAttribute('data-lume-icon') || this.options.icon || '';
    const dotCandidate = el.getAttribute('data-lume-dot') || this.options.dot || '';
    const dotProbe = document.createElement('span');
    dotProbe.style.backgroundColor = dotCandidate;
    const dot = dotProbe.style.backgroundColor ? dotCandidate : '';
    const requestedDotPosition =
      el.getAttribute('data-lume-dot-position') || this.options.dotPosition;
    const requestedAlign = el.getAttribute('data-lume-align') || this.options.align;
    const content = el.getAttribute('data-lume-content') || el.getAttribute('data-lume') || '';
    const direction = el.getAttribute('data-lume-direction') || 'top';
    const rawPriority = el.getAttribute('data-lume-priority');
    const prioritySource = rawPriority === null ? this.options.priority : rawPriority.split(',');
    const priority = [
      ...new Set(
        prioritySource
          .map((side) => side.trim())
          .filter((side) => ['top', 'bottom', 'right', 'left'].includes(side))
      ),
    ];
    const rawOffset = el.getAttribute('data-lume-offset');
    const offset = rawOffset !== null ? Number.parseInt(rawOffset, 10) : this.options.offset;
    const customClass = el.getAttribute('data-lume-class') || this.options.className;
    const requestedTier = el.getAttribute('data-lume-tier') || this.options.tier;
    const requestedMotion = el.getAttribute('data-lume-motion') || this.options.motion;
    const requestedAction = el.getAttribute('data-lume-action') || this.options.action;
    const rawSmart = el.getAttribute('data-lume-smart');
    const rawMotionIntensity = el.getAttribute('data-lume-intensity');
    const motionIntensity =
      rawMotionIntensity !== null
        ? Number.parseFloat(rawMotionIntensity)
        : this.options.motionIntensity;
    const motion = [
      'fade',
      'lift',
      'scale',
      'slide',
      'pop',
      'blur',
      'bounce',
      'swing',
      'flip',
      'none',
    ].includes(requestedMotion)
      ? requestedMotion
      : 'fade';

    return {
      title,
      icon,
      dot,
      dotPosition: ['left', 'right', 'top', 'bottom'].includes(requestedDotPosition)
        ? requestedDotPosition
        : 'left',
      align: ['left', 'center', 'right'].includes(requestedAlign) ? requestedAlign : 'center',
      content,
      direction: ['auto', 'top', 'bottom', 'left', 'right'].includes(direction) ? direction : 'top',
      priority: priority.length ? priority : this.options.priority,
      offset: Number.isNaN(offset) ? this.options.offset : offset,
      customClass,
      tier: ['minimal', 'simple', 'advanced'].includes(requestedTier) ? requestedTier : 'simple',
      motion,
      motionIntensity: Number.isFinite(motionIntensity)
        ? Math.max(0, Math.min(3, motionIntensity))
        : this.options.motionIntensity,
      action: ['hover', 'click'].includes(requestedAction) ? requestedAction : 'hover',
      smart: rawSmart === null ? this.options.smart : rawSmart !== 'false',
    };
  }

  /**
   * Converts the small Lume formatting vocabulary into DOM nodes without parsing HTML.
   * @param {string} value - Plain text with optional Lume formatting tokens.
   * @returns {DocumentFragment}
   * @private
   */
  _parseContent(value) {
    const fragment = document.createDocumentFragment();
    const stack = [{ name: null, node: fragment }];
    const tokenPattern = /\{([^{}]+)\}/g;
    const elements = {
      b: 'strong',
      i: 'em',
      c: 'code',
      s: 'small',
      l: 'span',
      u: 'u',
      mark: 'mark',
      kbd: 'kbd',
      ol: 'ol',
      ul: 'ul',
      li: 'li',
    };
    const semanticElements = {
      eyebrow: ['span', 'lume-eyebrow'],
      p: ['p', 'lume-paragraph'],
      row: ['div', 'lume-row'],
      label: ['span', 'lume-label'],
      value: ['span', 'lume-value'],
      chip: ['span', 'lume-chip'],
      foot: ['div', 'lume-foot'],
      emp: ['div', 'lume-emphasis'],
    };
    const compositeElements = new Set(['b', 'i', 'c', 's', 'l', 'u', 'mark', 'kbd']);
    const paletteNames = new Set([
      'blue',
      'mint',
      'peach',
      'lavender',
      'coral',
      'lemon',
      'sky',
      'rose',
    ]);
    let cursor = 0;
    let match;

    const appendText = (text) => {
      if (text) stack[stack.length - 1].node.appendChild(document.createTextNode(text));
    };

    while ((match = tokenPattern.exec(value)) !== null) {
      appendText(value.slice(cursor, match.index));
      const rawToken = match[1].trim();
      const token = rawToken.toLowerCase();

      if (token === 'br') {
        stack[stack.length - 1].node.appendChild(document.createElement('br'));
      } else if (token.startsWith('/')) {
        const closingToken = token.slice(1);
        const active = stack[stack.length - 1];
        if (
          stack.length > 1 &&
          (active.name === closingToken || active.closers?.includes(closingToken))
        ) {
          stack.pop();
        } else {
          appendText(match[0]);
        }
      } else if (token.includes(':')) {
        const styles = token
          .split(':')
          .map((style) => style.trim())
          .filter(Boolean);
        const validStyles =
          styles.length > 1 &&
          styles.every(
            (style) =>
              compositeElements.has(style) ||
              (style.startsWith('sp-') && paletteNames.has(style.slice(3)))
          );
        if (!validStyles) {
          appendText(match[0]);
        } else {
          let parent = stack[stack.length - 1].node;
          styles.forEach((style) => {
            const element = document.createElement(
              style.startsWith('sp-') ? 'span' : elements[style]
            );
            if (style === 'l') element.className = 'lume-large';
            if (style.startsWith('sp-')) element.className = `lume-sp-${style.slice(3)}`;
            parent.appendChild(element);
            parent = element;
          });
          stack.push({ name: 'lme', node: parent, closers: ['lme'] });
        }
      } else if (elements[token] || semanticElements[token]) {
        const definition = semanticElements[token] || [elements[token], null];
        const element = document.createElement(definition[0]);
        if (token === 'l') element.className = 'lume-large';
        if (definition[1]) element.className = definition[1];
        stack[stack.length - 1].node.appendChild(element);
        stack.push({ name: token, node: element, closers: [token, 'lme'] });
      } else {
        appendText(match[0]);
      }
      cursor = tokenPattern.lastIndex;
    }

    appendText(value.slice(cursor));
    return fragment;
  }

  /**
   * Schedules a single animation-frame position update.
   * @returns {void}
   */
  requestReposition() {
    if (!this.activeEl || !this.tooltip || this._repositionFrame !== null) return;
    this._repositionFrame = window.requestAnimationFrame(() => {
      this._repositionFrame = null;
      this.reposition();
    });
  }

  /**
   * Recalculates coordinates and updates tooltip position on screen.
   * @param {boolean} [activate=true] Whether to apply the active visual state.
   * @returns {void}
   */
  reposition(activate = true) {
    if (!this.activeEl || !this.tooltip) return;

    const config = this._getElementConfig(this.activeEl);
    const classNames = [
      'lume-tooltip',
      ...(activate ? ['lume-active'] : ['lume-positioning']),
      `lume-dir-${config.direction}`,
      `lume-motion-${config.motion}`,
      `lume-tier-${config.tier}`,
      ...(config.dot ? ['lume-has-dot', `lume-dot-${config.dotPosition}`] : []),
    ];
    if (config.customClass) {
      classNames.push(config.customClass);
    }
    this.tooltip.className = classNames.join(' ');

    const target = this.activeEl.getBoundingClientRect();
    const tip = this.tooltip.getBoundingClientRect();
    let dir = config.direction;
    const offset = config.offset;
    const positioningContainer =
      this.options.container && this.options.container !== document.body
        ? this.options.container
        : null;
    const containerRect = positioningContainer?.getBoundingClientRect();
    const containerScrollX = positioningContainer?.scrollLeft || 0;
    const containerScrollY = positioningContainer?.scrollTop || 0;
    const scrollY = window.pageYOffset || document.documentElement.scrollTop || 0;
    const scrollX = window.pageXOffset || document.documentElement.scrollLeft || 0;
    const coordinateX = positioningContainer
      ? target.left - containerRect.left + containerScrollX
      : target.left + scrollX;
    const coordinateY = positioningContainer
      ? target.top - containerRect.top + containerScrollY
      : target.top + scrollY;
    const coordinateRight = positioningContainer
      ? target.right - containerRect.left + containerScrollX
      : target.right + scrollX;
    const coordinateBottom = positioningContainer
      ? target.bottom - containerRect.top + containerScrollY
      : target.bottom + scrollY;
    const boundary = this.options.boundary || positioningContainer;
    const boundaryRect = boundary?.getBoundingClientRect();
    const boundaryWidth = boundary ? boundary.clientWidth : window.innerWidth;
    const boundaryHeight = boundary ? boundary.clientHeight : window.innerHeight;
    const boundaryLeft = boundary
      ? positioningContainer
        ? boundaryRect.left - containerRect.left + containerScrollX
        : boundaryRect.left + scrollX
      : scrollX;
    const boundaryTop = boundary
      ? positioningContainer
        ? boundaryRect.top - containerRect.top + containerScrollY
        : boundaryRect.top + scrollY
      : scrollY;
    const padding = Math.max(0, Number(this.options.padding) || 0);

    // Boundary collision logic. Auto chooses the side with the most available room.
    // A zero-sized trigger has no reliable geometry to collision-test (for
    // example during a jsdom update or before layout). Preserve an explicit
    // direction in that state; automatic placement still resolves normally.
    const canResolveCollision =
      config.direction === 'auto' || target.width > 0 || target.height > 0;
    if (config.smart && canResolveCollision) {
      const spaceTop = coordinateY - boundaryTop;
      const spaceBottom = boundaryTop + boundaryHeight - coordinateBottom;
      const spaceLeft = coordinateX - boundaryLeft;
      const spaceRight = boundaryLeft + boundaryWidth - coordinateRight;

      const spaces = { top: spaceTop, bottom: spaceBottom, right: spaceRight, left: spaceLeft };
      const fits = (side) => {
        if (side === 'top' || side === 'bottom') {
          const candidateLeft =
            config.align === 'left'
              ? coordinateX
              : config.align === 'right'
                ? coordinateRight - tip.width
                : coordinateX + target.width / 2 - tip.width / 2;
          return (
            spaces[side] >= tip.height + offset &&
            candidateLeft >= boundaryLeft + padding &&
            candidateLeft + tip.width <= boundaryLeft + boundaryWidth - padding
          );
        }
        const candidateTop = coordinateY + target.height / 2 - tip.height / 2;
        return (
          spaces[side] >= tip.width + offset &&
          candidateTop >= boundaryTop + padding &&
          candidateTop + tip.height <= boundaryTop + boundaryHeight - padding
        );
      };
      const fallback = config.priority.filter((side) => side !== dir);

      // Keep the requested side when it fits. Otherwise walk the caller's
      // priority list before choosing the side with the most available room.
      if (dir === 'auto' || !fits(dir)) {
        dir =
          (dir !== 'auto' && fits(dir) ? dir : undefined) ||
          fallback.find(fits) ||
          Object.entries(spaces).sort((a, b) => b[1] - a[1])[0][0];
      }
    }

    const activeClassNames = [
      'lume-tooltip',
      ...(activate ? ['lume-active'] : ['lume-positioning']),
      `lume-dir-${dir}`,
      `lume-motion-${config.motion}`,
      `lume-tier-${config.tier}`,
      ...(config.dot ? ['lume-has-dot', `lume-dot-${config.dotPosition}`] : []),
    ];
    if (config.customClass) {
      activeClassNames.push(config.customClass);
    }
    this.tooltip.className = activeClassNames.join(' ');

    let top = 0;
    let left = 0;

    switch (dir) {
      case 'top':
        top = coordinateY - tip.height - offset;
        left =
          config.align === 'left'
            ? coordinateX
            : config.align === 'right'
              ? coordinateRight - tip.width
              : coordinateX + target.width / 2 - tip.width / 2;
        break;
      case 'bottom':
        top = coordinateBottom + offset;
        left =
          config.align === 'left'
            ? coordinateX
            : config.align === 'right'
              ? coordinateRight - tip.width
              : coordinateX + target.width / 2 - tip.width / 2;
        break;
      case 'left':
        top = coordinateY + target.height / 2 - tip.height / 2;
        left = coordinateX - tip.width - offset;
        break;
      case 'right':
        top = coordinateY + target.height / 2 - tip.height / 2;
        left = coordinateRight + offset;
        break;
    }

    const minLeft = boundaryLeft + padding;
    const maxLeft = boundaryLeft + boundaryWidth - tip.width - padding;
    const minTop = boundaryTop + padding;
    const maxTop = boundaryTop + boundaryHeight - tip.height - padding;
    left = Math.max(minLeft, Math.min(left, maxLeft));
    top = Math.max(minTop, Math.min(top, maxTop));

    const targetCenterX = coordinateX + target.width / 2;
    const targetCenterY = coordinateY + target.height / 2;
    const arrowX = Math.max(12, Math.min(tip.width - 12, targetCenterX - left));
    const arrowY = Math.max(12, Math.min(tip.height - 12, targetCenterY - top));

    const motionX =
      config.motion === 'slide'
        ? dir === 'left'
          ? '6px'
          : dir === 'right'
            ? '-6px'
            : '0px'
        : '0px';
    const motionY =
      config.motion === 'lift'
        ? '6px'
        : config.motion === 'slide'
          ? dir === 'top'
            ? '6px'
            : dir === 'bottom'
              ? '-6px'
              : '0px'
          : '0px';
    this.tooltip.style.setProperty('--lume-x', `${Math.round(left)}px`);
    this.tooltip.style.setProperty('--lume-y', `${Math.round(top)}px`);
    this.tooltip.style.setProperty('--lume-from-x', motionX);
    this.tooltip.style.setProperty('--lume-from-y', motionY);
    this.tooltip.style.setProperty('--lume-motion-intensity', String(config.motionIntensity));
    this.tooltip.style.setProperty('--lume-arrow-x', `${Math.round(arrowX)}px`);
    this.tooltip.style.setProperty('--lume-arrow-y', `${Math.round(arrowY)}px`);
  }

  /**
   * Activates and positions tooltip for a specified target element.
   * @param {HTMLElement} el - Element to show tooltip for.
   * @returns {void}
   */
  show(el) {
    if (!el || !(el instanceof HTMLElement)) return;

    window.clearTimeout(this._hideTimer);
    window.clearTimeout(this._showTimer);
    const delay = Math.max(0, Number(this.options.showDelay) || 0);
    if (delay === 0) {
      this._showNow(el);
      return;
    }
    this._showTimer = window.setTimeout(() => this._showNow(el), delay);
  }

  /**
   * Populates and displays the reusable tooltip node without applying the show delay.
   * @param {HTMLElement} el - Trigger element to display.
   * @returns {void}
   * @private
   */
  _showNow(el) {
    if (!el || !(el instanceof HTMLElement)) return;

    if (!this.tooltip) {
      this._create();
    }

    // Prevent a reused node from animating out of its previous position.
    this.tooltip.style.display = 'none';

    const previousEl = this.activeEl;
    this.activeEl = el;
    const config = this._getElementConfig(el);

    const header = this.tooltip.querySelector('.lume-header');
    const content = this.tooltip.querySelector('.lume-content');

    if (header) {
      header.replaceChildren();
      let hasIcon = false;
      if (config.icon) {
        if (config.icon.toLowerCase() === 'info') {
          const icon = document.createElement('span');
          icon.className = 'lume-info-icon';
          icon.textContent = 'i';
          icon.setAttribute('aria-hidden', 'true');
          header.appendChild(icon);
          hasIcon = true;
        } else {
          try {
            const iconUrl = new URL(config.icon, document.baseURI);
            if (['http:', 'https:'].includes(iconUrl.protocol)) {
              const icon = document.createElement('img');
              icon.className = 'lume-title-icon';
              icon.src = iconUrl.href;
              icon.alt = '';
              icon.setAttribute('aria-hidden', 'true');
              header.appendChild(icon);
              hasIcon = true;
            }
          } catch {
            // Ignore invalid icon URLs and keep the title text available.
          }
        }
      }
      if (config.title) header.appendChild(this._parseContent(config.title));
      header.style.display = config.title || hasIcon ? 'flex' : 'none';
    }

    const dot = this.tooltip.querySelector('.lume-dot');
    if (dot instanceof HTMLElement) {
      dot.style.backgroundColor = '';
      if (config.dot) {
        dot.style.backgroundColor = config.dot;
        if (!dot.style.backgroundColor) {
          dot.removeAttribute('style');
        }
      }
    }

    if (content) {
      if (this.options.allowHTML) {
        content.innerHTML = config.content;
      } else {
        content.replaceChildren(this._parseContent(config.content));
      }
    }

    previousEl?.removeAttribute('aria-describedby');
    if (!this.tooltip.id) {
      tooltipIdCounter += 1;
      this.tooltip.id = `lume-tooltip-${tooltipIdCounter}`;
    }
    el.setAttribute('aria-describedby', this.tooltip.id);
    this.tooltip.setAttribute('aria-hidden', 'false');
    this.tooltip.style.display = 'flex';
    this.reposition(false);
    this.tooltip.classList.add('lume-no-entry');
    this.tooltip.classList.add('lume-active');
    window.setTimeout(() => {
      if (this.tooltip && this.activeEl === el) this.tooltip.classList.remove('lume-positioning');
    }, 0);

    if (typeof ResizeObserver !== 'undefined') {
      this._resizeObserver?.disconnect();
      this._resizeObserver = new ResizeObserver(() => this.requestReposition());
      this._resizeObserver.observe(this.tooltip);
      this._resizeObserver.observe(el);
    }

    window.addEventListener('scroll', this._scrollRef, { passive: true });
    window.addEventListener('resize', this._scrollRef, { passive: true });
  }

  /**
   * Deactivates the tooltip.
   * @returns {void}
   */
  hide() {
    window.clearTimeout(this._showTimer);
    window.clearTimeout(this._hideTimer);
    if (!this.tooltip) return;
    const delay = Math.max(0, Number(this.options.hideDelay) || 0);
    if (delay === 0) {
      this._hideNow();
      return;
    }
    this._hideTimer = window.setTimeout(() => this._hideNow(), delay);
  }

  /**
   * Updates the active trigger's data and refreshes the visible tooltip.
   * @param {HTMLElement} el - Trigger element to update.
   * @param {Partial<LumeElementConfig>} values - Values to write to the trigger.
   * @returns {void}
   */
  update(el, values = {}) {
    if (!el || !(el instanceof HTMLElement) || !values || typeof values !== 'object') return;
    const attributes = {
      title: 'data-lume-title',
      content: 'data-lume-content',
      direction: 'data-lume-direction',
      offset: 'data-lume-offset',
      motion: 'data-lume-motion',
      intensity: 'data-lume-intensity',
      action: 'data-lume-action',
      icon: 'data-lume-icon',
      align: 'data-lume-align',
      smart: 'data-lume-smart',
      tier: 'data-lume-tier',
      dot: 'data-lume-dot',
      dotPosition: 'data-lume-dot-position',
      priority: 'data-lume-priority',
    };
    for (const [key, attribute] of Object.entries(attributes)) {
      if (values[key] !== undefined) el.setAttribute(attribute, String(values[key]));
    }
    if (this.activeEl === el) this._showNow(el);
  }

  /**
   * Hides the tooltip immediately and removes active positioning listeners.
   * @returns {void}
   * @private
   */
  _hideNow() {
    if (this.tooltip) {
      this.tooltip.classList.remove('lume-active');
      this.tooltip.setAttribute('aria-hidden', 'true');
    }
    this.activeEl?.removeAttribute('aria-describedby');
    if (typeof window !== 'undefined') {
      window.removeEventListener('scroll', this._scrollRef);
      window.removeEventListener('resize', this._scrollRef);
    }
    if (this._repositionFrame !== null && typeof window !== 'undefined') {
      window.cancelAnimationFrame(this._repositionFrame);
      this._repositionFrame = null;
    }
    this._resizeObserver?.disconnect();
    this._resizeObserver = null;
    this.activeEl = null;
  }

  /**
   * Disconnects observers, event listeners, and removes the tooltip DOM node.
   * @returns {void}
   */
  destroy() {
    window.clearTimeout(this._showTimer);
    window.clearTimeout(this._hideTimer);
    this._hideNow();
    for (const [element, handlers] of this.elementHandlers) {
      element.removeEventListener('mouseenter', handlers.mouseenter);
      element.removeEventListener('mouseleave', handlers.mouseleave);
      element.removeEventListener('focus', handlers.focus);
      element.removeEventListener('blur', handlers.blur);
      element.removeEventListener('click', handlers.click);
      element.removeEventListener('keydown', handlers.keydown);
    }
    this.elementHandlers.clear();
    if (typeof document !== 'undefined') {
      document.removeEventListener('keydown', this._keyRef);
      document.removeEventListener('click', this._clickRef);
    }
    if (this.observer) {
      this.observer.disconnect();
      this.observer = null;
    }
    if (this.tooltip && this.tooltip.parentNode) {
      this.tooltip.parentNode.removeChild(this.tooltip);
      this.tooltip = null;
    }
    this.boundElements = new WeakSet();
  }
}

// Global auto-export / browser global attachment
if (typeof window !== 'undefined') {
  window.Lume = Lume;
}

export default Lume;
